// -----------------------------------------------------------------------------
// RevalidatingIdentityAuthenticationStateProvider.cs
// -----------------------------------------------------------------------------
// Provides a server-side authentication state provider that periodically
// revalidates the current user's identity using ASP.NET Core Identity. This
// ensures that changes to a user's security stamp (e.g., password change,
// account lockout) are reflected in the Blazor authentication state without
// requiring the user to sign out and back in.
// -----------------------------------------------------------------------------
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Options;
using System.Security.Claims;

namespace Bovis.Web.Areas.Identity
{
    /// <summary>
    /// A <see cref="RevalidatingServerAuthenticationStateProvider"/> implementation
    /// that uses ASP.NET Core Identity to periodically validate the current
    /// user's security stamp. The generic type parameter <typeparamref name="TUser"/>
    /// represents the user entity type used by the Identity system.
    /// </summary>
    /// <typeparam name="TUser">The type of the user entity.</typeparam>
    public class RevalidatingIdentityAuthenticationStateProvider<TUser>
        : RevalidatingServerAuthenticationStateProvider where TUser : class
    {
        private readonly IServiceScopeFactory _scopeFactory;
        private readonly IdentityOptions _options;

        /// <summary>
        /// Initializes a new instance of <see cref="RevalidatingIdentityAuthenticationStateProvider{TUser}"/>.
        /// </summary>
        /// <param name="loggerFactory">Factory used to create loggers for the base class.</param>
        /// <param name="scopeFactory">Factory used to create a new <see cref="IServiceScope"/> for each validation.</param>
        /// <param name="optionsAccessor">Provides access to the configured <see cref="IdentityOptions"/>.</param>
        public RevalidatingIdentityAuthenticationStateProvider(
            ILoggerFactory loggerFactory,
            IServiceScopeFactory scopeFactory,
            IOptions<IdentityOptions> optionsAccessor)
            : base(loggerFactory)
        {
            _scopeFactory = scopeFactory;
            _options = optionsAccessor.Value;
        }

        /// <summary>
        /// Gets the interval at which the authentication state should be revalidated.
        /// </summary>
        protected override TimeSpan RevalidationInterval => TimeSpan.FromMinutes(30);

        /// <summary>
        /// Validates the current authentication state by checking the user's security stamp.
        /// </summary>
        /// <param name="authenticationState">The current <see cref="AuthenticationState"/> to validate.</param>
        /// <param name="cancellationToken">A token to monitor for cancellation requests.</param>
        /// <returns>
        /// A <see cref="Task{Boolean}"/> that resolves to <c>true</c> if the authentication state
        /// remains valid; otherwise, <c>false</c>.
        /// </returns>
        protected override async Task<bool> ValidateAuthenticationStateAsync(
            AuthenticationState authenticationState, CancellationToken cancellationToken)
        {
            // Create a new DI scope so that we obtain a fresh UserManager instance,
            // ensuring we read the latest user data from the store.
            var scope = _scopeFactory.CreateScope();
            try
            {
                var userManager = scope.ServiceProvider.GetRequiredService<UserManager<TUser>>();
                // Delegate the actual stamp comparison to a helper method.
                return await ValidateSecurityStampAsync(userManager, authenticationState.User);
            }
            finally
            {
                // Properly dispose the scope. Prefer asynchronous disposal when available.
                if (scope is IAsyncDisposable asyncDisposable)
                {
                    await asyncDisposable.DisposeAsync();
                }
                else
                {
                    scope.Dispose();
                }
            }
        }

        /// <summary>
        /// Compares the security stamp stored in the user's claims with the stamp
        /// retrieved from the Identity store.
        /// </summary>
        /// <param name="userManager">The <see cref="UserManager{TUser}"/> used to query user data.</param>
        /// <param name="principal">The <see cref="ClaimsPrincipal"/> representing the current user.</param>
        /// <returns>
        /// A <see cref="Task{Boolean}"/> that resolves to <c>true</c> if the stamps match
        /// (or if the user manager does not support security stamps); otherwise, <c>false</c>.
        /// </returns>
        private async Task<bool> ValidateSecurityStampAsync(UserManager<TUser> userManager, ClaimsPrincipal principal)
        {
            var user = await userManager.GetUserAsync(principal);
            if (user == null)
            {
                // No user could be found for the principal; the authentication state is invalid.
                return false;
            }
            else if (!userManager.SupportsUserSecurityStamp)
            {
                // The user manager does not support security stamps; assume the state is valid.
                return true;
            }
            else
            {
                // Retrieve the stamp from the claims and compare it to the current stamp in the store.
                var principalStamp = principal.FindFirstValue(_options.ClaimsIdentity.SecurityStampClaimType);
                var userStamp = await userManager.GetSecurityStampAsync(user);
                return principalStamp == userStamp;
            }
        }
    }
}
